// Meta's one-time subscription handshake: echo hub.challenge back verbatim,
// but only when the token matches.
const q = $json.query ?? {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.META_VERIFY_TOKEN;
return { json: { ok, challenge: ok ? q['hub.challenge'] : 'verification failed' } };

// Meta signs the raw body with the app secret. Verify before parsing, and
// flatten the page/IG event shapes into one message record per comment or DM.
const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers ?? {};

// With rawBody enabled the body arrives as base64 binary; fall back to the
// parsed object if the option is ever turned off.
let raw;
if (item.binary?.data?.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else {
  raw = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body ?? {});
}

const secret = $env.META_APP_SECRET;
if (secret) {
  const provided = String(headers['x-hub-signature-256'] ?? '');
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(provided, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error('Meta webhook signature mismatch — request rejected.');
  }
} else {
  console.warn('META_APP_SECRET unset — webhook signature NOT verified. Anyone can post to this URL.');
}

const payload = JSON.parse(raw);
const platform = payload.object === 'instagram' ? 'instagram' : 'facebook';
const out = [];

for (const entry of payload.entry ?? []) {
  // Comments on posts (both networks use `changes`, with different field names)
  for (const change of entry.changes ?? []) {
    const v = change.value ?? {};

    if (change.field === 'feed' && v.item === 'comment' && v.verb === 'add') {
      out.push({
        json: {
          platform: 'facebook',
          kind: 'comment',
          externalId: v.comment_id,
          authorName: v.from?.name ?? 'Facebook user',
          authorHandle: v.from?.id,
          message: v.message ?? '',
          permalink: v.post_id ? `https://www.facebook.com/${v.post_id}` : undefined,
        },
      });
    }

    if (change.field === 'comments') {
      out.push({
        json: {
          platform: 'instagram',
          kind: 'comment',
          externalId: v.id,
          authorName: v.from?.username ?? 'Instagram user',
          authorHandle: v.from?.username,
          message: v.text ?? '',
          permalink: v.media?.id ? `https://www.instagram.com/p/${v.media.id}` : undefined,
        },
      });
    }
  }

  // Direct messages
  for (const m of entry.messaging ?? []) {
    if (!m.message?.text) continue;
    if (m.message.is_echo) continue; // our own outbound message coming back
    out.push({
      json: {
        platform,
        kind: 'direct_message',
        externalId: m.message.mid,
        authorName: 'Unknown',
        authorHandle: m.sender?.id,
        message: m.message.text,
      },
    });
  }
}

// Ignore our own comments and anything with no text to judge.
const pageIds = String($env.OWN_ACTOR_IDS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
return out.filter((o) => o.json.message.trim() && !pageIds.includes(String(o.json.authorHandle)));

